//! First executable M1 style-trajectory realization.
//!
//! This deliberately supports one qualified pair only:
//! Classical (PeriodSentence) -> Minimalism (ProcessAdditive).
//! Both segment scores are generated by their real typed grammar engines.
//! The current Score schema has one tempo and meter, so this path rejects any
//! clock mismatch instead of retiming a segment or pretending a time map exists.
//!
//! PartId::UNASSIGNED remains unknown. This module never infers persistent part
//! identity or motif lineage from role, register, pitch, timing or event order.

use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use symthaea_music_theory::{
    AssertedObligationState, Duration, Emphasis, GrammarPlanEvidence, GrammarStructuralTrace,
    MusicalIntent, Score, ScoreValidationConfig, ScoreValidationIssue, Style, VoiceRole,
    StyleTrajectoryPlanV1, StyleTrajectorySegmentV1, StyleTrajectoryTransitionV1,
    StyleTransitionMode, TheoryValidationReport, ValidationSeverity,
    compose_with_grammar_plan, validate_score,
};
use symthaea_music_theory::score_validation::is_universal_invariant;
use symthaea_music_theory::process_grammar::{
    verify_additive_process_score_v1, ProcessRealizationAuditError, ProcessRealizationAuditV1,
};
use symthaea_muse_protocol::catalog::{CATALOG, StyleStatus};
use symthaea_muse_protocol::{
    EvidenceBasis, EvidenceStatus, ListenCompositionBundle, MeterPoint, MotifDefinition,
    MusicalTime, SymbolicNoteEvent, TempoPoint, TraceVerificationIssue,
    TraceVerificationReport, VerificationStatus,
};

use crate::analyst::{composer_trace_from_theory, verify_composer_trace};

use crate::style_trajectory_admission::{
    SOURCE_SCORE_DIGEST_SCHEMA_V1, StyleTrajectoryAdmissionError,
    admit_style_trajectory_for_score, style_profile_sha256_v1,
};

/// Shared-arousal point inside the Classical/Minimalism tempo-range intersection.
/// Both current style specs resolve this value to 140 BPM.
pub const M1_SHARED_AROUSAL: f32 = 8.0 / 9.0;
pub const M1_TRAJECTORY_SCHEMA_VERSION: u16 = 1;
/// Canonical serialization domain for per-segment evidence hashes.
pub const M1_SEGMENT_EVIDENCE_DIGEST_SCHEMA_V1: &str =
    "muse-m1-segment-evidence-serde-json-sha256-v1";
/// Canonical serialization domain for complete M1 receipt hashes.
pub const M1_RECEIPT_DIGEST_SCHEMA_V1: &str =
    "muse-m1-receipt-serde-json-sha256-v1";

const CLASSICAL_SEGMENT_ID: &str = "classical-period-sentence";
const MINIMALISM_SEGMENT_ID: &str = "minimalism-process-additive";

#[derive(Clone, Debug, PartialEq)]
pub enum StyleTrajectoryM1Error {
    ClockMismatch {
        classical_tempo: f32,
        minimalism_tempo: f32,
        classical_meter: u8,
        minimalism_meter: u8,
    },
    KeyMismatch {
        classical_key: String,
        minimalism_key: String,
    },
    CatalogueRouteMissing {
        style: String,
    },
    CatalogueRouteNotComposable {
        style: String,
    },
    UnexpectedGrammarEvidence {
        style: String,
        reason: String,
    },
    InvalidProcessPlan {
        reason: String,
    },
    ProcessRealizationAudit(ProcessRealizationAuditError),
    ReceiptSchemaVersionMismatch { expected: u16, actual: u16 },
    ReceiptDigestMismatch { expected: String, actual: String },
    ReceiptSerializationFailed { reason: String },
    ReceiptSegmentCountMismatch { expected: usize, actual: usize },
    ReceiptIntentMissing,
    ReceiptIntentBindingMismatch,
    ReceiptSegmentIdentityMismatch { segment_index: usize },
    ReceiptSegmentIntervalMismatch { segment_id: String },
    ReceiptSegmentClockMismatch { segment_id: String },
    ReceiptSegmentEvidenceDigestMismatch { segment_id: String },
    ReceiptSegmentScoreDigestMismatch { segment_id: String, expected: String, actual: String },
    ReceiptTraceVerificationMismatch { segment_id: String },
    ReceiptSegmentValidationMismatch { segment_id: String },
    ReceiptComposedScoreDigestMismatch { expected: String, actual: String },
    ReceiptComposedScoreMismatch,
    ReceiptBoundaryEvidenceMismatch,
    ReceiptTransitionMismatch,
    ReceiptProcessAuditMissing,
    ReceiptProcessAuditUnexpected,
    ReceiptProcessAuditMismatch,
    ReceiptComposedValidationMismatch,
    ReceiptExpertReviewStatusMismatch,
    UniversalInvariantViolation {
        style: String,
        issues: Vec<ScoreValidationIssue>,
    },
    IndependentTraceVerificationFailed {
        style: String,
        issues: Vec<TraceVerificationIssue>,
        verification_status: VerificationStatus,
    },
    ScoreSerializationFailed {
        reason: String,
    },
    Admission(StyleTrajectoryAdmissionError),
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct StyleTrajectoryM1SegmentV1 {
    pub segment_id: String,
    pub style: Style,
    /// Absolute start beat in the composed score.
    pub start_beat: Duration,
    /// Exclusive end beat in the composed score.
    pub end_beat: Duration,
    /// Digest of this local segment Score, before timeline offsetting.
    pub segment_score_sha256: String,
    pub score: Score,
    pub grammar_plan: GrammarPlanEvidence,
    /// ScoreEventRef values in this trace are local to this segment Score.
    pub grammar_trace: GrammarStructuralTrace,
    /// Independently checks composer assertions against score-derived Listen events.
    pub trace_verification: TraceVerificationReport,
    /// Score-side semantic audit for ProcessAdditive; absent for other grammars.
    /// This report proves only the versioned symbolic ProcessAdditive contract.
    #[serde(default)]
    pub process_realization_audit: Option<ProcessRealizationAuditV1>,
    pub validation: TheoryValidationReport,
    /// SHA-256 binding the complete segment evidence envelope. This is a
    /// content address, not an author signature; pin it in an outer trusted
    /// receipt/ledger when tamper evidence across storage boundaries matters.
    #[serde(default)]
    pub evidence_sha256: String,
}

/// Score-domain evidence around an explicit hard boundary. These are
/// descriptive measurements, not a perceptual quality judgment.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct StyleTrajectoryM1BoundaryEvidenceV1 {
    pub boundary_beat: Duration,
    pub left_last_event_end: Duration,
    /// Onsets are local to the target segment, whose origin is the boundary.
    pub right_first_event_start: Duration,
    pub left_tail_gap: Duration,
    pub right_entry_gap: Duration,
    /// Event counts in the final/initial four-beat windows.
    pub left_events_in_window: usize,
    pub right_events_in_window: usize,
    /// Must be zero for this hard-boundary implementation.
    pub cross_boundary_event_count: usize,
}

/// Result of the first real two-family symbolic trajectory.
/// The composed Score and plan are digest-bound. Segment-local score/trace
/// material is retained so each grammar can be inspected independently.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct StyleTrajectoryM1ResultV1 {
    pub schema_version: u16,
    pub seed: u64,
    pub arousal: f32,
    /// Full immutable generation input required to replay trace verification.
    /// Missing intent in legacy receipts remains deserializable but cannot be
    /// promoted to a verified M1 receipt.
    #[serde(default)]
    pub intent: Option<MusicalIntent>,
    pub composed_score: Score,
    pub composed_score_sha256: String,
    pub composed_validation: TheoryValidationReport,
    pub segments: Vec<StyleTrajectoryM1SegmentV1>,
    pub transition_at_beat: Duration,
    pub boundary_evidence: StyleTrajectoryM1BoundaryEvidenceV1,
    pub plan: StyleTrajectoryPlanV1,
    /// True when catalogue metadata says expert review is required.
    /// It is not evidence that the review has happened.
    pub expert_review_required: bool,
    /// Content hash over the complete result except this field itself.
    /// It is not a digital signature or proof of authorship.
    #[serde(default)]
    pub receipt_sha256: String,
}

/// Summary of independently replaying one serialized M1 receipt.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct StyleTrajectoryM1ReceiptVerificationV1 {
    pub schema_version: u16,
    pub receipt_sha256: String,
    pub verified_segment_count: usize,
    pub trace_integrity_verified_segment_count: usize,
    pub process_additive_score_verified_segment_count: usize,
    /// False until the PeriodSentence score-semantic oracle is integrated.
    pub period_sentence_semantics_verified: bool,
    pub total_beats: Duration,
}

/// Compose the first M1 trajectory using Classical then Minimalism.
///
/// The same frozen intent/seed is sent to both real grammar engines. Both
/// segment Scores must agree on the single tempo and meter supported by the
/// current Score type. The combined Score uses exact rational beat offsets.
/// This is a symbolic experiment; no renderer/audio quality is claimed.
pub fn realize_classical_to_minimalism_m1(
    intent: MusicalIntent,
) -> Result<StyleTrajectoryM1ResultV1, StyleTrajectoryM1Error> {
    let styles = [Style::Classical, Style::Minimalism];
    let specs = [styles[0].spec(), styles[1].spec()];

    let realized: Vec<_> = styles
        .iter()
        .zip(specs.iter())
        .map(|(style, spec)| compose_with_grammar_plan(style.grammar_profile(), &intent, spec))
        .collect();

    let classical = &realized[0];
    let minimalism = &realized[1];

    // Score has one global clock. Compare the engine outputs themselves;
    // matching configured ranges alone is not enough.
    if classical.score.tempo_bpm.to_bits() != minimalism.score.tempo_bpm.to_bits()
        || classical.score.meter != minimalism.score.meter
    {
        return Err(StyleTrajectoryM1Error::ClockMismatch {
            classical_tempo: classical.score.tempo_bpm,
            minimalism_tempo: minimalism.score.tempo_bpm,
            classical_meter: classical.score.meter,
            minimalism_meter: minimalism.score.meter,
        });
    }

    if classical.score.key != minimalism.score.key {
        return Err(StyleTrajectoryM1Error::KeyMismatch {
            classical_key: format!("{:?}", classical.score.key),
            minimalism_key: format!("{:?}", minimalism.score.key),
        });
    }

    verify_typed_grammar(Style::Classical, &classical.plan, &classical.trace, &classical.score)?;
    verify_typed_grammar(
        Style::Minimalism,
        &minimalism.plan,
        &minimalism.trace,
        &minimalism.score,
    )?;

    // Unlike trace-integrity verification, this re-derives the current
    // ProcessAdditive score contract from its typed plan and rejects a score
    // that does not realize the declared cycle, source cell, dynamics or clock.
    let minimalism_process_realization_audit = match &minimalism.plan {
        GrammarPlanEvidence::AdditiveProcess(process) => {
            verify_additive_process_score_v1(process, &minimalism.score)
                .map_err(StyleTrajectoryM1Error::ProcessRealizationAudit)?
        }
        _ => {
            return Err(StyleTrajectoryM1Error::UnexpectedGrammarEvidence {
                style: "Minimalism".into(),
                reason: "Minimalism requires typed ProcessAdditive evidence for independent score audit".into(),
            });
        }
    };

    let classical_validation = validate_universal_invariants(Style::Classical, &classical.score)?;
    let minimalism_validation =
        validate_universal_invariants(Style::Minimalism, &minimalism.score)?;
    let classical_trace_verification = verify_trace_independently(
        Style::Classical,
        &intent,
        &classical.score,
        &classical.trace,
    )?;
    let minimalism_trace_verification = verify_trace_independently(
        Style::Minimalism,
        &intent,
        &minimalism.score,
        &minimalism.trace,
    )?;

    let classical_length = classical.score.total_beats;
    let minimalism_start = classical_length;
    let total_beats = classical_length + minimalism.score.total_beats;

    if !is_positive_duration(classical_length)
        || !is_positive_duration(minimalism.score.total_beats)
        || !is_positive_duration(total_beats)
    {
        return Err(StyleTrajectoryM1Error::UnexpectedGrammarEvidence {
            style: "M1-pair".into(),
            reason: "one or more realized segment durations are non-positive".into(),
        });
    }

    let mut composed_score = Score::new(
        classical.score.key,
        classical.score.tempo_bpm,
        classical.score.meter,
    );

    // Preserve all source note fields. Only the second segment's absolute
    // onset is offset. Segment-local evidence is retained separately below.
    composed_score.notes.reserve(classical.score.notes.len() + minimalism.score.notes.len());
    composed_score.notes.extend(classical.score.notes.iter().copied());
    composed_score.notes.extend(minimalism.score.notes.iter().copied().map(|mut note| {
        note.onset = note.onset + minimalism_start;
        note
    }));
    composed_score.total_beats = total_beats;

    let composed_validation = validate_universal_invariants(Style::Classical, &composed_score)?;
    let boundary_evidence = measure_hard_boundary(&classical.score, &minimalism.score, minimalism_start)?;
    let composed_score_sha256 = score_sha256(&composed_score)?;
    let classical_id = catalogue_id_for_style(Style::Classical)?;
    let minimalism_id = catalogue_id_for_style(Style::Minimalism)?;
    let classical_profile_sha = style_profile_sha256_v1(Style::Classical)
        .map_err(StyleTrajectoryM1Error::Admission)?;
    let minimalism_profile_sha = style_profile_sha256_v1(Style::Minimalism)
        .map_err(StyleTrajectoryM1Error::Admission)?;

    let mut segments = vec![
        StyleTrajectoryM1SegmentV1 {
            segment_id: CLASSICAL_SEGMENT_ID.into(),
            style: Style::Classical,
            start_beat: Duration::zero(),
            end_beat: classical_length,
            segment_score_sha256: score_sha256(&classical.score)?,
            score: classical.score.clone(),
            grammar_plan: classical.plan.clone(),
            grammar_trace: classical.trace.clone(),
            trace_verification: classical_trace_verification,
            process_realization_audit: None,
            validation: classical_validation,
            evidence_sha256: String::new(),
        },
        StyleTrajectoryM1SegmentV1 {
            segment_id: MINIMALISM_SEGMENT_ID.into(),
            style: Style::Minimalism,
            start_beat: minimalism_start,
            end_beat: total_beats,
            segment_score_sha256: score_sha256(&minimalism.score)?,
            score: minimalism.score.clone(),
            grammar_plan: minimalism.plan.clone(),
            grammar_trace: minimalism.trace.clone(),
            trace_verification: minimalism_trace_verification,
            process_realization_audit: Some(minimalism_process_realization_audit),
            validation: minimalism_validation,
            evidence_sha256: String::new(),
        },
    ];

    for segment in &mut segments {
        segment.evidence_sha256 = segment_evidence_sha256_v1(segment)?;
    }

    let plan = StyleTrajectoryPlanV1 {
        schema_version: symthaea_music_theory::STYLE_TRAJECTORY_SCHEMA_VERSION,
        source_score_sha256: composed_score_sha256.clone(),
        source_score_digest_schema: SOURCE_SCORE_DIGEST_SCHEMA_V1.into(),
        total_beats,
        segments: vec![
            StyleTrajectorySegmentV1 {
                segment_id: CLASSICAL_SEGMENT_ID.into(),
                start_beat: Duration::zero(),
                end_beat: classical_length,
                structural_owner_ref: format!("catalog-style:{classical_id}"),
                profile_ref: format!("catalog-style:{classical_id}"),
                profile_sha256: classical_profile_sha,
            },
            StyleTrajectorySegmentV1 {
                segment_id: MINIMALISM_SEGMENT_ID.into(),
                start_beat: minimalism_start,
                end_beat: total_beats,
                structural_owner_ref: format!("catalog-style:{minimalism_id}"),
                profile_ref: format!("catalog-style:{minimalism_id}"),
                profile_sha256: minimalism_profile_sha,
            },
        ],
        transitions: vec![StyleTrajectoryTransitionV1 {
            transition_id: "classical-to-minimalism-hard-boundary".into(),
            from_segment_id: CLASSICAL_SEGMENT_ID.into(),
            to_segment_id: MINIMALISM_SEGMENT_ID.into(),
            mode: StyleTransitionMode::HardBoundary,
        }],
    };

    // Final source-bound admission proves the exact composed-score digest,
    // total duration and current catalogue/profile references all agree.
    let admission = admit_style_trajectory_for_score(&plan, &composed_score)
        .map_err(StyleTrajectoryM1Error::Admission)?;

    let mut result = StyleTrajectoryM1ResultV1 {
        schema_version: M1_TRAJECTORY_SCHEMA_VERSION,
        seed: intent.seed,
        arousal: intent.arousal,
        intent: Some(intent),
        composed_score,
        composed_score_sha256,
        composed_validation,
        segments,
        transition_at_beat: minimalism_start,
        boundary_evidence,
        plan,
        expert_review_required: admission.expert_review_required,
        receipt_sha256: String::new(),
    };
    result.receipt_sha256 = m1_receipt_sha256_v1(&result)?;
    Ok(result)
}

/// Independently replay and verify a serialized Classical -> Minimalism M1 receipt.
///
/// The verifier re-hashes every segment evidence envelope and the complete
/// receipt, recomputes segment-score digests, reconstructs the composed Score
/// from the segment-local source Scores, replays universal validation and
/// Muse Analyst trace verification, reruns the ProcessAdditive score oracle,
/// validates catalogue/profile admission, and recomputes the hard-boundary
/// evidence. Legacy receipts without the full intent or digests remain
/// deserializable but are not upgraded to a verified result.
///
/// SHA-256 here establishes content integrity relative to a pinned digest. It
/// does not establish who authored the receipt: the digest must be anchored in
/// a separately trusted store or signed by an external authority for that.
pub fn verify_classical_to_minimalism_m1_receipt_v1(
    result: &StyleTrajectoryM1ResultV1,
) -> Result<StyleTrajectoryM1ReceiptVerificationV1, StyleTrajectoryM1Error> {
    if result.schema_version != M1_TRAJECTORY_SCHEMA_VERSION {
        return Err(StyleTrajectoryM1Error::ReceiptSchemaVersionMismatch {
            expected: M1_TRAJECTORY_SCHEMA_VERSION,
            actual: result.schema_version,
        });
    }
    if result.segments.len() != 2 {
        return Err(StyleTrajectoryM1Error::ReceiptSegmentCountMismatch {
            expected: 2,
            actual: result.segments.len(),
        });
    }
    let intent = result.intent.ok_or(StyleTrajectoryM1Error::ReceiptIntentMissing)?;
    if intent.seed != result.seed || intent.arousal.to_bits() != result.arousal.to_bits() {
        return Err(StyleTrajectoryM1Error::ReceiptIntentBindingMismatch);
    }

    let actual_receipt_sha256 = m1_receipt_sha256_v1(result)?;
    if actual_receipt_sha256 != result.receipt_sha256 {
        return Err(StyleTrajectoryM1Error::ReceiptDigestMismatch {
            expected: result.receipt_sha256.clone(),
            actual: actual_receipt_sha256,
        });
    }

    let expected_styles = [Style::Classical, Style::Minimalism];
    let expected_ids = [CLASSICAL_SEGMENT_ID, MINIMALISM_SEGMENT_ID];
    for (index, segment) in result.segments.iter().enumerate() {
        if segment.style != expected_styles[index] || segment.segment_id != expected_ids[index] {
            return Err(StyleTrajectoryM1Error::ReceiptSegmentIdentityMismatch {
                segment_index: index,
            });
        }

        let actual_evidence_sha256 = segment_evidence_sha256_v1(segment)?;
        if actual_evidence_sha256 != segment.evidence_sha256 {
            return Err(StyleTrajectoryM1Error::ReceiptSegmentEvidenceDigestMismatch {
                segment_id: segment.segment_id.clone(),
            });
        }

        let actual_segment_sha256 = score_sha256(&segment.score)?;
        if actual_segment_sha256 != segment.segment_score_sha256 {
            return Err(StyleTrajectoryM1Error::ReceiptSegmentScoreDigestMismatch {
                segment_id: segment.segment_id.clone(),
                expected: segment.segment_score_sha256.clone(),
                actual: actual_segment_sha256,
            });
        }

        let replayed_validation = validate_universal_invariants(segment.style, &segment.score)?;
        if replayed_validation != segment.validation {
            return Err(StyleTrajectoryM1Error::ReceiptSegmentValidationMismatch {
                segment_id: segment.segment_id.clone(),
            });
        }
        verify_typed_grammar(
            segment.style,
            &segment.grammar_plan,
            &segment.grammar_trace,
            &segment.score,
        )?;
        let replayed_trace = verify_trace_independently(
            segment.style,
            &intent,
            &segment.score,
            &segment.grammar_trace,
        )?;
        if replayed_trace != segment.trace_verification {
            return Err(StyleTrajectoryM1Error::ReceiptTraceVerificationMismatch {
                segment_id: segment.segment_id.clone(),
            });
        }

        if segment.score.key != result.composed_score.key
            || segment.score.tempo_bpm.to_bits() != result.composed_score.tempo_bpm.to_bits()
            || segment.score.meter != result.composed_score.meter
        {
            return Err(StyleTrajectoryM1Error::ReceiptSegmentClockMismatch {
                segment_id: segment.segment_id.clone(),
            });
        }
    }

    let classical = &result.segments[0];
    let minimalism = &result.segments[1];
    let classical_length = classical.score.total_beats;
    let minimalism_length = minimalism.score.total_beats;
    let expected_total = classical_length + minimalism_length;
    if classical.start_beat != Duration::zero()
        || classical.end_beat != classical_length
        || minimalism.start_beat != classical.end_beat
        || minimalism.end_beat != expected_total
        || minimalism.end_beat != result.composed_score.total_beats
        || result.plan.total_beats != expected_total
    {
        return Err(StyleTrajectoryM1Error::ReceiptSegmentIntervalMismatch {
            segment_id: "trajectory".into(),
        });
    }
    if result.transition_at_beat != minimalism.start_beat
        || result.plan.segments.len() != 2
        || result.plan.segments[0].segment_id != classical.segment_id
        || result.plan.segments[0].start_beat != classical.start_beat
        || result.plan.segments[0].end_beat != classical.end_beat
        || result.plan.segments[1].segment_id != minimalism.segment_id
        || result.plan.segments[1].start_beat != minimalism.start_beat
        || result.plan.segments[1].end_beat != minimalism.end_beat
        || result.plan.transitions.len() != 1
        || result.plan.transitions[0].from_segment_id != classical.segment_id
        || result.plan.transitions[0].to_segment_id != minimalism.segment_id
        || result.plan.transitions[0].mode != StyleTransitionMode::HardBoundary
    {
        return Err(StyleTrajectoryM1Error::ReceiptTransitionMismatch);
    }

    let mut reconstructed = Score::new(
        classical.score.key,
        classical.score.tempo_bpm,
        classical.score.meter,
    );
    reconstructed
        .notes
        .reserve(classical.score.notes.len() + minimalism.score.notes.len());
    reconstructed.notes.extend(classical.score.notes.iter().copied());
    reconstructed.notes.extend(minimalism.score.notes.iter().copied().map(|mut note| {
        note.onset = note.onset + minimalism.start_beat;
        note
    }));
    reconstructed.total_beats = expected_total;
    if reconstructed != result.composed_score {
        return Err(StyleTrajectoryM1Error::ReceiptComposedScoreMismatch);
    }

    let actual_composed_sha256 = score_sha256(&result.composed_score)?;
    if actual_composed_sha256 != result.composed_score_sha256
        || result.plan.source_score_sha256 != result.composed_score_sha256
    {
        return Err(StyleTrajectoryM1Error::ReceiptComposedScoreDigestMismatch {
            expected: result.composed_score_sha256.clone(),
            actual: actual_composed_sha256,
        });
    }

    let admission = admit_style_trajectory_for_score(&result.plan, &result.composed_score)
        .map_err(StyleTrajectoryM1Error::Admission)?;
    if admission.expert_review_required != result.expert_review_required {
        return Err(StyleTrajectoryM1Error::ReceiptExpertReviewStatusMismatch);
    }

    let replayed_composed_validation =
        validate_universal_invariants(Style::Classical, &result.composed_score)?;
    if replayed_composed_validation != result.composed_validation {
        return Err(StyleTrajectoryM1Error::ReceiptComposedValidationMismatch);
    }

    if classical.process_realization_audit.is_some() {
        return Err(StyleTrajectoryM1Error::ReceiptProcessAuditUnexpected);
    }
    let process_plan = match &minimalism.grammar_plan {
        GrammarPlanEvidence::AdditiveProcess(process) => process,
        _ => {
            return Err(StyleTrajectoryM1Error::UnexpectedGrammarEvidence {
                style: "Minimalism".into(),
                reason: "receipt replay requires typed ProcessAdditive evidence".into(),
            });
        }
    };
    let replayed_process_audit =
        verify_additive_process_score_v1(process_plan, &minimalism.score)
            .map_err(StyleTrajectoryM1Error::ProcessRealizationAudit)?;
    let stored_process_audit = minimalism
        .process_realization_audit
        .as_ref()
        .ok_or(StyleTrajectoryM1Error::ReceiptProcessAuditMissing)?;
    if &replayed_process_audit != stored_process_audit {
        return Err(StyleTrajectoryM1Error::ReceiptProcessAuditMismatch);
    }

    let replayed_boundary =
        measure_hard_boundary(&classical.score, &minimalism.score, minimalism.start_beat)?;
    if replayed_boundary != result.boundary_evidence {
        return Err(StyleTrajectoryM1Error::ReceiptBoundaryEvidenceMismatch);
    }

    Ok(StyleTrajectoryM1ReceiptVerificationV1 {
        schema_version: 1,
        receipt_sha256: result.receipt_sha256.clone(),
        verified_segment_count: 2,
        trace_integrity_verified_segment_count: 2,
        process_additive_score_verified_segment_count: 1,
        period_sentence_semantics_verified: false,
        total_beats: result.composed_score.total_beats,
    })
}

/// Hash a segment's score, grammar plan/trace, verification and validation
/// report. The segment hash field itself is excluded from its own material.
fn segment_evidence_sha256_v1(
    segment: &StyleTrajectoryM1SegmentV1,
) -> Result<String, StyleTrajectoryM1Error> {
    let material = (
        M1_SEGMENT_EVIDENCE_DIGEST_SCHEMA_V1,
        &segment.segment_id,
        &segment.style,
        segment.start_beat,
        segment.end_beat,
        &segment.segment_score_sha256,
        &segment.score,
        &segment.grammar_plan,
        &segment.grammar_trace,
        &segment.trace_verification,
        &segment.process_realization_audit,
        &segment.validation,
    );
    let bytes = serde_json::to_vec(&material).map_err(|error| {
        StyleTrajectoryM1Error::ReceiptSerializationFailed {
            reason: error.to_string(),
        }
    })?;
    Ok(format!("{:x}", Sha256::digest(bytes)))
}

/// Hash the complete result while excluding only receipt_sha256 itself.
fn m1_receipt_sha256_v1(
    result: &StyleTrajectoryM1ResultV1,
) -> Result<String, StyleTrajectoryM1Error> {
    let material = (
        M1_RECEIPT_DIGEST_SCHEMA_V1,
        result.schema_version,
        result.seed,
        result.arousal,
        result.intent,
        &result.composed_score,
        &result.composed_score_sha256,
        &result.composed_validation,
        &result.segments,
        result.transition_at_beat,
        &result.boundary_evidence,
        &result.plan,
        result.expert_review_required,
    );
    let bytes = serde_json::to_vec(&material).map_err(|error| {
        StyleTrajectoryM1Error::ReceiptSerializationFailed {
            reason: error.to_string(),
        }
    })?;
    Ok(format!("{:x}", Sha256::digest(bytes)))
}

fn verify_typed_grammar(
    style: Style,
    plan: &GrammarPlanEvidence,
    trace: &GrammarStructuralTrace,
    score: &Score,
) -> Result<(), StyleTrajectoryM1Error> {
    let (expected_obligation, plan_ok) = match (style, plan) {
        (Style::Classical, GrammarPlanEvidence::PeriodSentence(period)) => (
            "thematic-return-and-closure",
            period.section_count > 0,
        ),
        (Style::Minimalism, GrammarPlanEvidence::AdditiveProcess(process)) => {
            if process.prefix_lengths.is_empty()
                || process.prefix_lengths.len() != process.cycle_starts.len()
                || process.prefix_lengths.iter().any(|length| *length == 0)
                || process.cycle_starts.first().copied() != Some(Duration::zero())
                || process.cycle_starts.windows(2).any(|pair| {
                    !duration_less_than(pair[0], pair[1])
                })
                || process
                    .cycle_starts
                    .last()
                    .copied()
                    .map_or(true, |start| !duration_less_than(start, score.total_beats))
            {
                return Err(StyleTrajectoryM1Error::InvalidProcessPlan {
                    reason: "prefix lengths/cycle starts are empty, misaligned, non-monotonic or outside the score".into(),
                });
            }
            ("audible-grow-shrink-rule", true)
        }
        _ => {
            return Err(StyleTrajectoryM1Error::UnexpectedGrammarEvidence {
                style: format!("{style:?}"),
                reason: format!("unexpected or generic grammar plan: {plan:?}"),
            });
        }
    };

    if !plan_ok {
        return Err(StyleTrajectoryM1Error::UnexpectedGrammarEvidence {
            style: format!("{style:?}"),
            reason: "typed grammar plan has no realized structural sections".into(),
        });
    }
    if trace.structures.is_empty() {
        return Err(StyleTrajectoryM1Error::UnexpectedGrammarEvidence {
            style: format!("{style:?}"),
            reason: "typed grammar realization emitted no score-local structural trace".into(),
        });
    }
    let obligation_fulfilled = trace.obligation_transitions.iter().any(|item| {
        item.obligation_id == expected_obligation
            && item.to == AssertedObligationState::Fulfilled
            && !item.evidence.is_empty()
    });
    if !obligation_fulfilled {
        return Err(StyleTrajectoryM1Error::UnexpectedGrammarEvidence {
            style: format!("{style:?}"),
            reason: format!("missing fulfilled trace for {expected_obligation}"),
        });
    }
    Ok(())
}

fn verify_trace_independently(
    style: Style,
    intent: &MusicalIntent,
    score: &Score,
    trace: &GrammarStructuralTrace,
) -> Result<TraceVerificationReport, StyleTrajectoryM1Error> {
    let digest = score_sha256(score)?;
    let public_trace = composer_trace_from_theory(trace, &digest, 0, None);
    let composition = listen_bundle_for_score(style, intent, score);
    let report = verify_composer_trace(&public_trace, &composition, &digest, 0);
    if !report.issues.is_empty()
        || report.evidence.verification_status != VerificationStatus::Verified
    {
        return Err(StyleTrajectoryM1Error::IndependentTraceVerificationFailed {
            style: format!("{style:?}"),
            issues: report.issues.clone(),
            verification_status: report.evidence.verification_status.clone(),
        });
    }
    Ok(report)
}

/// Build the same score-event identity projection used by Muse Studio and
/// the existing Analyst flagship-verification tests. IDs are role-local
/// ordinals scoped to this frozen segment Score, never global EventIds.
fn listen_bundle_for_score(
    style: Style,
    intent: &MusicalIntent,
    score: &Score,
) -> ListenCompositionBundle {
    let mut notes = Vec::with_capacity(score.notes.len());
    for role in [
        VoiceRole::Bass,
        VoiceRole::Harmony,
        VoiceRole::CounterMelody,
        VoiceRole::Melody,
    ] {
        let role_slug = match role {
            VoiceRole::Melody => "melody",
            VoiceRole::Harmony => "harmony",
            VoiceRole::Bass => "bass",
            VoiceRole::CounterMelody => "counter",
        };
        let role_label = format!("{role:?}");
        for (index, note) in score.voice(role).into_iter().enumerate() {
            let onset = note.onset.beats();
            let duration_beats = note.duration.beats();
            notes.push(SymbolicNoteEvent {
                id: format!("score-{role_slug}-{index}"),
                midi: note.pitch.midi(),
                pitch_name: format!("{:?}", note.pitch),
                onset: musical_time(onset, score.tempo_bpm),
                duration_ticks: (duration_beats * 480.0).round() as u64,
                duration_beats,
                duration_seconds: note.duration.seconds(score.tempo_bpm as f64),
                velocity: note.velocity,
                voice_role: role_label.clone(),
                emphasis: match note.emphasis {
                    Emphasis::Normal => "normal",
                    Emphasis::Climax => "climax",
                    Emphasis::Cadential => "cadential",
                    Emphasis::PhraseStart => "phrase-start",
                }
                .into(),
                section_intensity: note.section_intensity,
            });
        }
    }

    // The trace verifier needs the same motif-family identity named by
    // composer_trace_from_theory. The definition is recipe-derived metadata;
    // actual occurrence validity is still checked against score event IDs.
    let motif = style.spec().motif(intent.arousal, intent.seed);
    let pitched: Vec<_> = motif
        .notes
        .iter()
        .filter_map(|note| note.degree.map(|degree| (degree, note.duration.beats())))
        .collect();
    let motif_definition = MotifDefinition {
        id: "motif-primary".into(),
        label: format!("{style:?} primary recipe motif"),
        degrees: pitched.iter().map(|item| item.0).collect(),
        durations_beats: pitched.iter().map(|item| item.1).collect(),
        basis: EvidenceBasis {
            status: EvidenceStatus::Observed,
            source_method: "builtin-style-spec-motif-v1".into(),
            confidence: None,
            limitations: vec![
                "The definition records the configured source motif; it is not a listener-recognition claim.".into(),
            ],
        },
    };

    ListenCompositionBundle {
        ticks_per_beat: 480,
        duration_ticks: (score.total_beats.beats() * 480.0).round() as u64,
        duration_beats: score.total_beats.beats(),
        duration_seconds: score.seconds(),
        form_kind: format!("{:?}", style.grammar_family()),
        tempo_map: vec![TempoPoint {
            at: musical_time(0.0, score.tempo_bpm),
            bpm: score.tempo_bpm,
        }],
        meter_map: vec![MeterPoint {
            at: musical_time(0.0, score.tempo_bpm),
            numerator: score.meter,
            denominator: 4,
        }],
        sections: Vec::new(),
        phrases: Vec::new(),
        notes,
        motif_definitions: vec![motif_definition],
        motif_occurrences: Vec::new(),
        cadences: Vec::new(),
        sonorities: Vec::new(),
        orchestration: Vec::new(),
        resonance: None,
    }
}

fn musical_time(beats: f64, tempo_bpm: f32) -> MusicalTime {
    MusicalTime {
        tick: (beats.max(0.0) * 480.0).round() as u64,
        beats,
        seconds: beats * 60.0 / tempo_bpm.max(1.0) as f64,
    }
}

fn measure_hard_boundary(
    left: &Score,
    right: &Score,
    boundary: Duration,
) -> Result<StyleTrajectoryM1BoundaryEvidenceV1, StyleTrajectoryM1Error> {
    let left_last_event_end = left
        .notes
        .iter()
        .map(|note| note.onset + note.duration)
        .max_by(|a, b| duration_cmp(*a, *b))
        .ok_or_else(|| StyleTrajectoryM1Error::UnexpectedGrammarEvidence {
            style: "Classical".into(),
            reason: "cannot measure boundary from an empty source segment".into(),
        })?;
    let right_first_event_start = right
        .notes
        .iter()
        .map(|note| note.onset)
        .min_by(|a, b| duration_cmp(*a, *b))
        .ok_or_else(|| StyleTrajectoryM1Error::UnexpectedGrammarEvidence {
            style: "Minimalism".into(),
            reason: "cannot measure boundary from an empty target segment".into(),
        })?;

    let left_window_start = boundary.saturating_sub(Duration::new(4, 1));
    let left_events_in_window = left
        .notes
        .iter()
        .filter(|note| {
            !duration_less_than(note.onset, left_window_start)
                && duration_less_than(note.onset, boundary)
        })
        .count();
    let right_window_end = Duration::new(4, 1);
    let right_events_in_window = right
        .notes
        .iter()
        .filter(|note| duration_less_than(note.onset, right_window_end))
        .count();

    let left_overruns = left
        .notes
        .iter()
        .filter(|note| duration_less_than(boundary, note.onset + note.duration))
        .count();
    let right_precedes = right
        .notes
        .iter()
        .filter(|note| duration_less_than(note.onset, Duration::zero()))
        .count();

    Ok(StyleTrajectoryM1BoundaryEvidenceV1 {
        boundary_beat: boundary,
        left_last_event_end,
        right_first_event_start,
        left_tail_gap: boundary.saturating_sub(left_last_event_end),
        right_entry_gap: right_first_event_start,
        left_events_in_window,
        right_events_in_window,
        cross_boundary_event_count: left_overruns + right_precedes,
    })
}

fn duration_cmp(left: Duration, right: Duration) -> std::cmp::Ordering {
    match (
        duration_less_than(left, right),
        duration_less_than(right, left),
    ) {
        (true, false) => std::cmp::Ordering::Less,
        (false, true) => std::cmp::Ordering::Greater,
        _ => std::cmp::Ordering::Equal,
    }
}

fn validate_universal_invariants(
    style: Style,
    score: &Score,
) -> Result<TheoryValidationReport, StyleTrajectoryM1Error> {
    let report = validate_score(score, &ScoreValidationConfig::default());
    let issues: Vec<_> = report
        .issues
        .iter()
        .filter(|issue| {
            issue.severity == ValidationSeverity::Fatal && is_universal_invariant(issue.rule)
        })
        .cloned()
        .collect();
    if !issues.is_empty() {
        return Err(StyleTrajectoryM1Error::UniversalInvariantViolation {
            style: format!("{style:?}"),
            issues,
        });
    }
    Ok(report)
}

fn catalogue_id_for_style(style: Style) -> Result<u16, StyleTrajectoryM1Error> {
    let name = format!("{style:?}");
    let Some(entry) = CATALOG
        .iter()
        .find(|entry| entry.composer_style == Some(name.as_str()))
    else {
        return Err(StyleTrajectoryM1Error::CatalogueRouteMissing { style: name });
    };
    if !entry.is_composable()
        || entry.status == StyleStatus::Research
    {
        return Err(StyleTrajectoryM1Error::CatalogueRouteNotComposable { style: name });
    }
    Ok(entry.id)
}

fn score_sha256(score: &Score) -> Result<String, StyleTrajectoryM1Error> {
    let bytes = serde_json::to_vec(score).map_err(|error| {
        StyleTrajectoryM1Error::ScoreSerializationFailed {
            reason: error.to_string(),
        }
    })?;
    Ok(format!("{:x}", Sha256::digest(bytes)))
}

fn is_positive_duration(value: Duration) -> bool {
    value.den() > 0 && value.num() > 0
}

fn duration_less_than(left: Duration, right: Duration) -> bool {
    (left.num() as i128) * (right.den() as i128)
        < (right.num() as i128) * (left.den() as i128)
}

#[cfg(test)]
mod tests {
    use super::*;
    use symthaea_music_theory::{Key, PartId, Pitch, PitchClass, ScoreNote};

    fn fixture_score(notes: Vec<ScoreNote>, total_beats: i64) -> Score {
        let mut score = Score::new(Key::major(PitchClass::C), 120.0, 4);
        score.notes = notes;
        score.total_beats = Duration::new(total_beats, 1);
        score
    }

    fn fixture_note(onset: i64, duration: i64) -> ScoreNote {
        ScoreNote {
            part: PartId::UNASSIGNED,
            pitch: Pitch::new(PitchClass::C, 4),
            onset: Duration::new(onset, 1),
            duration: Duration::new(duration, 1),
            velocity: 0.7,
            role: VoiceRole::Melody,
            emphasis: Emphasis::Normal,
            section_intensity: 1.0,
        }
    }

    fn m1_intent(arousal: f32) -> MusicalIntent {
        MusicalIntent {
            valence: 0.25,
            arousal,
            energy: 0.7,
            bars: 4,
            seed: 11,
            tonic: PitchClass::C,
        }
    }

    #[test]
    fn realizes_two_typed_grammars_on_the_same_exact_clock() {
        let result = realize_classical_to_minimalism_m1(m1_intent(M1_SHARED_AROUSAL))
            .expect("the selected shared-clock pair should realize");
        assert_eq!(result.segments.len(), 2);
        assert_eq!(result.composed_score.tempo_bpm, 140.0);
        assert_eq!(result.composed_score.meter, 4);
        assert_eq!(result.boundary_evidence.boundary_beat, result.transition_at_beat);
        assert_eq!(result.boundary_evidence.left_tail_gap, Duration::zero());
        assert_eq!(result.boundary_evidence.right_entry_gap, Duration::zero());
        assert_eq!(result.boundary_evidence.cross_boundary_event_count, 0);
        assert!(result.boundary_evidence.left_events_in_window > 0);
        assert!(result.boundary_evidence.right_events_in_window > 0);
        assert_eq!(result.segments[0].style, Style::Classical);
        assert_eq!(result.segments[1].style, Style::Minimalism);
        assert!(matches!(
            &result.segments[0].grammar_plan,
            GrammarPlanEvidence::PeriodSentence(_)
        ));
        assert!(matches!(
            &result.segments[1].grammar_plan,
            GrammarPlanEvidence::AdditiveProcess(_)
        ));
        assert_eq!(result.plan.segments[0].start_beat, Duration::zero());
        assert_eq!(
            result.plan.segments[0].end_beat,
            result.plan.segments[1].start_beat
        );
        assert_eq!(
            result.plan.segments[1].end_beat,
            result.composed_score.total_beats
        );
        assert!(result.plan.source_score_sha256 == result.composed_score_sha256);
        assert!(result.composed_score_sha256.len() == 64);
        assert!(result.segments.iter().all(|segment| segment.validation.issues.iter().all(|issue| {
            issue.severity != ValidationSeverity::Fatal || !is_universal_invariant(issue.rule)
        })));
        assert!(result.composed_validation.issues.iter().all(|issue| {
            issue.severity != ValidationSeverity::Fatal || !is_universal_invariant(issue.rule)
        }));
        assert!(result.segments.iter().all(|segment| segment.trace_verification.issues.is_empty()));
        assert!(result.segments.iter().all(|segment| {
            segment.trace_verification.evidence.verification_status == VerificationStatus::Verified
        }));
        assert!(!result.segments[1].score.has_part_identity());
    }

    #[test]
    fn rejects_tempo_mismatch_instead_of_retiming_a_segment() {
        let error = realize_classical_to_minimalism_m1(m1_intent(0.5)).unwrap_err();
        assert!(matches!(error, StyleTrajectoryM1Error::ClockMismatch { .. }));
    }

    #[test]
    fn same_frozen_intent_and_seed_replay_identically() {
        let intent = m1_intent(M1_SHARED_AROUSAL);
        let left = realize_classical_to_minimalism_m1(intent).unwrap();
        let right = realize_classical_to_minimalism_m1(intent).unwrap();
        assert_eq!(left, right);
        assert_eq!(left.composed_score_sha256, right.composed_score_sha256);
    }

    #[test]
    fn boundary_evidence_reports_source_tail_and_target_entry_gaps() {
        let left = fixture_score(vec![fixture_note(0, 3)], 4);
        let right = fixture_score(vec![fixture_note(1, 1)], 2);
        let evidence =
            measure_hard_boundary(&left, &right, Duration::new(4, 1)).unwrap();
        assert_eq!(evidence.left_last_event_end, Duration::new(3, 1));
        assert_eq!(evidence.right_first_event_start, Duration::new(1, 1));
        assert_eq!(evidence.left_tail_gap, Duration::new(1, 1));
        assert_eq!(evidence.right_entry_gap, Duration::new(1, 1));
        assert_eq!(evidence.cross_boundary_event_count, 0);
    }

    #[test]
    fn boundary_evidence_detects_an_event_that_crosses_the_boundary() {
        let left = fixture_score(vec![fixture_note(3, 2)], 5);
        let right = fixture_score(vec![fixture_note(0, 1)], 1);
        let evidence =
            measure_hard_boundary(&left, &right, Duration::new(4, 1)).unwrap();
        assert_eq!(evidence.left_last_event_end, Duration::new(5, 1));
        assert_eq!(evidence.cross_boundary_event_count, 1);
    }

    #[test]
    fn all_events_stay_inside_their_exact_segment_window() {
        let result = realize_classical_to_minimalism_m1(m1_intent(M1_SHARED_AROUSAL)).unwrap();
        for (index, segment) in result.segments.iter().enumerate() {
            let duration = segment.end_beat.saturating_sub(segment.start_beat);
            for note in &segment.score.notes {
                let end = note.onset + note.duration;
                assert!(!duration_less_than(duration, end));
                assert!(!duration_less_than(note.onset, Duration::zero()));
            }
            if index == 1 {
                assert!(segment.score.notes.iter().all(|note| {
                    let shifted = note.onset + segment.start_beat;
                    !duration_less_than(shifted, result.transition_at_beat)
                }));
            }
        }
    }
    #[test]
    fn minimalism_segment_carries_independent_process_score_audit() {
        let result = realize_classical_to_minimalism_m1(m1_intent(M1_SHARED_AROUSAL))
            .expect("shared-clock M1 realization should pass the process score audit");
        assert!(result.segments[0].process_realization_audit.is_none());
        let report = result.segments[1]
            .process_realization_audit
            .as_ref()
            .expect("Minimalism segment must retain its independent audit receipt");
        let GrammarPlanEvidence::AdditiveProcess(process) = &result.segments[1].grammar_plan
        else {
            panic!("Minimalism must retain typed AdditiveProcess evidence");
        };
        assert_eq!(report.schema_version, 1);
        assert_eq!(report.cycle_count, process.prefix_lengths.len());
        assert_eq!(
            report.observed_melody_event_count,
            report.verified_expressive_event_count
        );
        assert!(report.verified_harmony_event_count > 0);
        assert!(report.verified_bass_event_count > 0);
        assert_eq!(
            report.maximum_prefix_length,
            *process.prefix_lengths.iter().max().expect("non-empty process")
        );
    }

    #[test]
    fn m1_receipt_replays_after_json_round_trip() {
        let generated =
            realize_classical_to_minimalism_m1(m1_intent(M1_SHARED_AROUSAL)).unwrap();
        let encoded = serde_json::to_vec(&generated).unwrap();
        let decoded: StyleTrajectoryM1ResultV1 = serde_json::from_slice(&encoded).unwrap();
        let verified = verify_classical_to_minimalism_m1_receipt_v1(&decoded).unwrap();
        assert_eq!(verified.schema_version, 1);
        assert_eq!(verified.verified_segment_count, 2);
        assert_eq!(verified.trace_integrity_verified_segment_count, 2);
        assert_eq!(verified.process_additive_score_verified_segment_count, 1);
        assert!(!verified.period_sentence_semantics_verified);
        assert_eq!(verified.total_beats, decoded.composed_score.total_beats);
        assert_eq!(verified.receipt_sha256, decoded.receipt_sha256);
    }

    #[test]
    fn m1_receipt_rejects_mutation_when_the_pinned_receipt_digest_is_unchanged() {
        let mut result =
            realize_classical_to_minimalism_m1(m1_intent(M1_SHARED_AROUSAL)).unwrap();
        result.boundary_evidence.left_events_in_window += 1;
        let error = verify_classical_to_minimalism_m1_receipt_v1(&result).unwrap_err();
        assert!(matches!(error, StyleTrajectoryM1Error::ReceiptDigestMismatch { .. }));
    }

    #[test]
    fn m1_receipt_rejects_segment_evidence_mutation_even_if_outer_digest_is_recomputed() {
        let mut result =
            realize_classical_to_minimalism_m1(m1_intent(M1_SHARED_AROUSAL)).unwrap();
        result.segments[1].grammar_trace.structures.clear();
        result.segments[1].evidence_sha256 =
            segment_evidence_sha256_v1(&result.segments[1]).unwrap();
        result.receipt_sha256 = m1_receipt_sha256_v1(&result).unwrap();
        let error = verify_classical_to_minimalism_m1_receipt_v1(&result).unwrap_err();
        assert!(matches!(
            error,
            StyleTrajectoryM1Error::ReceiptTraceVerificationMismatch { .. }
                | StyleTrajectoryM1Error::UnexpectedGrammarEvidence { .. }
        ));
    }

    #[test]
    fn m1_receipt_rejects_process_audit_report_mutation_after_rehash() {
        let mut result =
            realize_classical_to_minimalism_m1(m1_intent(M1_SHARED_AROUSAL)).unwrap();
        result.segments[1]
            .process_realization_audit
            .as_mut()
            .unwrap()
            .verified_harmony_event_count += 1;
        result.segments[1].evidence_sha256 =
            segment_evidence_sha256_v1(&result.segments[1]).unwrap();
        result.receipt_sha256 = m1_receipt_sha256_v1(&result).unwrap();
        let error = verify_classical_to_minimalism_m1_receipt_v1(&result).unwrap_err();
        assert!(matches!(error, StyleTrajectoryM1Error::ReceiptProcessAuditMismatch));
    }

    #[test]
    fn m1_receipt_reconstructs_composed_score_and_rejects_score_mutation() {
        let mut result =
            realize_classical_to_minimalism_m1(m1_intent(M1_SHARED_AROUSAL)).unwrap();
        result.segments[1].score.notes[0].pitch =
            Pitch::from_midi(result.segments[1].score.notes[0].pitch.midi().wrapping_add(1));
        result.segments[1].segment_score_sha256 =
            score_sha256(&result.segments[1].score).unwrap();
        result.segments[1].evidence_sha256 =
            segment_evidence_sha256_v1(&result.segments[1]).unwrap();
        result.receipt_sha256 = m1_receipt_sha256_v1(&result).unwrap();
        let error = verify_classical_to_minimalism_m1_receipt_v1(&result).unwrap_err();
        assert!(matches!(
            error,
            StyleTrajectoryM1Error::ProcessRealizationAudit(_)
                | StyleTrajectoryM1Error::ReceiptComposedScoreMismatch
        ));
    }


}
